/// <summary>
/// Employee selection form for order generation.
/// Reads from NVOrderStaging (Regular table) filtered by BatchId.
/// Allows users to select employees and generate employment orders.
/// </summary>
/// <remarks>
/// Form flow: NVGenerateOrder -> NVOrderSelection -> generates orders -> notifies NVOrderList
///
/// Data pattern: NVOrderStaging (Regular table), BatchId isolation per session.
/// No TempDB instance linking required — data visible across all AOS connections.
/// Cleanup: delete_from NVOrderStaging where BatchId on close().
/// </remarks>
[Form]
public class NVOrderSelection extends FormRun
{
    /// <summary>
    /// Control reference for the consolidation checkbox.
    /// </summary>
    FormCheckBoxControl isConsolidateCtrl;

    /// <summary>
    /// Stores the consolidation mode selection.
    /// </summary>
    boolean isConsolidateHeader;

    /// <summary>
    /// BatchId received from NVGenerateOrder via args.parm().
    /// Used to filter NVOrderStaging datasource.
    /// </summary>
    str batchId;

    /// <summary>
    /// Label control displaying count of selected employees.
    /// </summary>
    FormStringControl selectedCountLabel;

}

/// <summary>
/// Initializes the form, validates BatchId, sets datasource range.
/// </summary>
public void init()
{
    batchId = element.args() ? element.args().parm() : '';

    if (!batchId)
    {
        error("Invalid session. Please reopen from Generate Order.");
        element.close();
        return;
    }

    super();

    // Set range AFTER super() — Microsoft standard pattern (see SalesEditLines.init())
    // NVOrderStaging is Regular table — standard query range works correctly
    NVOrderStaging_ds
        .query()
        .dataSourceTable(tableNum(NVOrderStaging))
        .addRange(fieldNum(NVOrderStaging, BatchId))
        .value(queryValue(batchId));

    NVOrderStaging_ds.executeQuery();

    // Diagnostic: verify records are visible
    NVOrderStaging checkStaging;
    select count(RecId) from checkStaging
        where checkStaging.BatchId == batchId;

    // Initialize selected count label control
    selectedCountLabel = element.design().controlName('SelectedCountLabel') as FormStringControl;
}

/// <summary>
/// Runs the form and initializes the selection counter.
/// </summary>
public void run()
{
    super();
    this.setDefaultOrderDate();
    NVOrderStaging_ds.executeQuery();
    this.updateSelectedCount();
}

/// <summary>
/// On close — delete NVOrderStaging records for this session.
/// </summary>
public void close()
{
    NVOrderStaging staging;

    if (batchId)
    {
        delete_from staging
            where staging.BatchId == batchId;
    }

    super();
}

/// <summary>
/// Gets or sets the consolidation mode flag.
/// </summary>
public boolean parmIsConsolidateHeader(boolean _set = false, boolean _value = false)
{
    if (_set)
        isConsolidateHeader = _value;

    return isConsolidateHeader;
}

/// <summary>
/// Notifies NVOrderList to refresh after order generation.
/// Caller is NVOrderList directly — NVGenerateOrder passes its own caller in args.
/// </summary>
private void notifyParentToRefresh()
{
    #Task
    FormRun parent = element.args() ? element.args().caller() : null;

    if (!parent)
        return;

    // Standard Microsoft pattern — works regardless of caller type
    parent.task(#taskRefresh);
}

/// <summary>
/// Handles OK button click — validates selection, generates orders, notifies parent.
/// </summary>
public void closeOk()
{
    if (!this.validateSelection())
        return;

    this.generateOrders();

    super(); // close form first

    this.notifyParentToRefresh(); // then notify parent
}

/// <summary>
/// Updates the selected employee counter label.
/// </summary>
public void updateSelectedCount()
{
    NVOrderStaging staging;
    int            totalCount    = 0;
    int            selectedCount = 0;

    // Total count for this session
    select count(RecId) from staging
        where staging.BatchId == batchId;
    totalCount = staging.RecId;

    // Selected count via datasource marker
    staging = NVOrderStaging_ds.getFirst(true);
    while (staging)
    {
        selectedCount++;
        staging = NVOrderStaging_ds.getNext();
    }

    if (selectedCountLabel)
        selectedCountLabel.text(strFmt("Selected: %1 of %2", selectedCount, totalCount));
}

/// <summary>
/// Sets default order date (today) for all staging records in this session.
/// </summary>
private void setDefaultOrderDate()
{
    NVOrderStaging staging;

    ttsbegin;
    while select forupdate staging
        where staging.BatchId == batchId
    {
        if (!staging.OrderDate)
        {
            staging.OrderDate = today();
            staging.update();
        }
    }
    ttscommit;
}

/// <summary>
/// Validates employee selection before order generation.
/// </summary>
private boolean validateSelection()
{
    NVOrderStaging staging;
    int            selectedCount = 0;
    NVOrderType    firstOrderType;

    staging = NVOrderStaging_ds.getFirst(true);
    while (staging)
    {
        if (selectedCount == 0)
            firstOrderType = staging.OrderType;
        else if (staging.OrderType != firstOrderType)
        {
            error("All selected employees must have the same Order Type.");
            return false;
        }

        selectedCount++;
        staging = NVOrderStaging_ds.getNext();
    }

    if (selectedCount == 0)
    {
        error("Please select at least one employee.");
        return false;
    }

    staging = NVOrderStaging_ds.getFirst(true);
    if (!staging.OrderDate || staging.OrderDate == dateNull())
    {
        error("Order Date is required.");
        return false;
    }

    return true;
}

/// <summary>
/// Generates sequential order number. Format: ORD-{N}
/// </summary>
