/// <summary>
/// Gets the starting number for order number generation.
/// Called ONCE before the transaction to avoid reading uncommitted data inside tts.
/// </summary>
private int getNextOrderNumberSeed()
{
    NVOrderHeader lastOrder;
    NVOrderHeader checkOrder;
    int           nextNumber = 1;

    select firstonly lastOrder
    order by RecId desc;

    if (lastOrder.OrderNumber)
    {
        str numPart = subStr(lastOrder.OrderNumber, 5, strLen(lastOrder.OrderNumber) - 4);
        int parsed  = str2Int(numPart);

        if (parsed > 0)
        nextNumber = parsed + 1;
    }

    // Verify uniqueness — handles gaps, deleted records, and edge cases
    // This runs OUTSIDE ttsbegin so all committed records are visible
    do
    {
        select firstonly RecId from checkOrder
        where checkOrder.OrderNumber == strFmt("ORD-%1", int2Str(nextNumber));

        if (checkOrder.RecId)
        nextNumber++;
    }
    while (checkOrder.RecId);

    return nextNumber;
}

/// <summary>
/// Formats order number from integer seed. Format: ORD-{N}
/// </summary>
private str formatOrderNumber(int _number)
{
    return strFmt("ORD-%1", int2Str(_number));
}

/// <summary>
/// Generates employment orders based on selection and consolidation mode.
/// Consolidated: one header, multiple lines.
/// Individual: one header per employee, one line each.
/// </summary>
private void generateOrders()
{
    NVOrderHeader  header;
    NVOrderLine    line;
    NVOrderStaging staging;
    int            lineCounter  = 0;
    int            orderCounter = 0;
    boolean        consolidate  = element.parmIsConsolidateHeader();

    // Read seed BEFORE ttsbegin — inside tts, new uncommitted headers are invisible
    // to subsequent selects, causing duplicate OrderNumber generation.
    int nextOrderNumber = this.getNextOrderNumberSeed();

    ttsbegin;

    if (consolidate)
    {
        staging = NVOrderStaging_ds.getFirst(true);

        if (!staging)
        {
            error("No employees selected.");
            ttsabort;
            return;
        }

        // Single header for all selected employees
        header.clear();
        header.initValue();
        header.OrderNumber    = this.formatOrderNumber(nextOrderNumber);
        header.OrderDate      = staging.OrderDate;
        header.StartDate      = staging.StartDate;
        header.EndDate        = staging.EndDate;
        header.IsConsolidated = NoYes::Yes;
        header.Status         = NVOrderStatus::Draft;
        // Workflow routing fields — populated from staging record (all lines share same group/type)
        header.OrderGroupRecId = staging.OrderGroupRecId;
        header.OrderType       = staging.OrderType;
        header.insert();

        lineCounter = 1;
        while (staging)
        {
            line.clear();
            line.initValue();
            line.OrderHeaderRecId = header.RecId;
            line.OrderType        = staging.OrderType;
            line.LineNum          = lineCounter;
            line.WorkerRecId      = staging.WorkerRecId;
            line.EmploymentRecId  = staging.EmploymentRecId;
            line.PositionRecId    = staging.PositionRecId;
            line.DepartmentRecId  = staging.DepartmentRecId;
            line.StartDate        = staging.StartDate;
            line.EndDate          = staging.EndDate;
            line.ProbationPeriod  = staging.ProbationPeriod;
            line.GovernmentGrade  = staging.GovernmentGrade;
            line.BaseSalary       = staging.BaseSalary;
            line.AdditionalSalary = staging.AdditionalSalary;
            line.HazardousConditionsPercent  = staging.HazardousConditionsPercent;
            line.ContractDate     = staging.ContractDate;
            // Position Change fields — populated only for types 17/18, zero/empty for others
            line.PreviousDepartmentRecId = staging.PreviousDepartmentRecId;
            line.ChangeDate              = staging.ChangeDate;
            line.StaffUnitBefore         = staging.StaffUnitBefore;
            line.WorkSchedule            = staging.WorkSchedule;
            line.AdditionalSalaryBefore  = staging.AdditionalSalaryBefore;
            line.NVDepartBU              = staging.NVDepartBU;
            line.NVDepartGroup1          = staging.NVDepartGroup1;
            line.NVDepartGroup2          = staging.NVDepartGroup2;
            line.insert();

            lineCounter++;
            staging = NVOrderStaging_ds.getNext();
        }

        orderCounter = 1;
    }
    else
    {
        // Individual header per employee
        staging = NVOrderStaging_ds.getFirst(true);

        while (staging)
        {
            header.clear();
            header.initValue();
            header.OrderNumber    = this.formatOrderNumber(nextOrderNumber);
            header.OrderDate      = staging.OrderDate;
            header.StartDate      = staging.StartDate;
            header.EndDate        = staging.EndDate;
            header.IsConsolidated = NoYes::No;
            header.Status         = NVOrderStatus::Draft;
            // Workflow routing fields — populated from staging record
            header.OrderGroupRecId = staging.OrderGroupRecId;
            header.OrderType       = staging.OrderType;
            header.insert();

            nextOrderNumber++; // Increment after header

            line.clear();
            line.initValue();
            line.OrderHeaderRecId = header.RecId;
            line.OrderType        = staging.OrderType;
            line.LineNum          = 1;
            line.WorkerRecId      = staging.WorkerRecId;
            line.EmploymentRecId  = staging.EmploymentRecId;
            line.PositionRecId    = staging.PositionRecId;
            line.DepartmentRecId  = staging.DepartmentRecId;
            line.StartDate        = staging.StartDate;
            line.EndDate          = staging.EndDate;
            line.ProbationPeriod  = staging.ProbationPeriod;
            line.GovernmentGrade  = staging.GovernmentGrade;
            line.BaseSalary       = staging.BaseSalary;
            line.AdditionalSalary = staging.AdditionalSalary;
            line.HazardousConditionsPercent  = staging.HazardousConditionsPercent;
            line.ContractDate     = staging.ContractDate;
            // Position Change fields — populated only for types 17/18, zero/empty for others
            line.PreviousDepartmentRecId = staging.PreviousDepartmentRecId;
            line.ChangeDate              = staging.ChangeDate;
            // NEW: Work Schedule and Previous Additional Salary
            line.WorkSchedule            = staging.WorkSchedule;
            line.AdditionalSalaryBefore  = staging.AdditionalSalaryBefore;
            line.StaffUnitBefore         = staging.StaffUnitBefore;
            line.NVDepartBU              = staging.NVDepartBU;
            line.NVDepartGroup1          = staging.NVDepartGroup1;
            line.NVDepartGroup2          = staging.NVDepartGroup2;
            line.insert();

            orderCounter++;
            staging = NVOrderStaging_ds.getNext();
        }
    }

    ttscommit;
}

/// <summary>
/// Standard init — no linkPhysicalTableInstance needed.
/// NVOrderStaging is Regular table, visible across all AOS connections.
/// </summary>
public void init()
{
    super();
}

/// <summary>
/// Fires when user marks/unmarks rows — updates selection counter.
/// </summary>
public void markChanged()
{
    super();
    element.updateSelectedCount();
}

/// <summary>
/// Saves consolidation mode to form class variable.
/// </summary>
public boolean modified()
{
    boolean ret       = super();
    boolean isChecked = this.value() ? true : false;

    element.parmIsConsolidateHeader(true, isChecked);

    return ret;
}
